-- memoriahub-db baseline (RETRO-J3, #606): the whole MemoriaHub domain schema in its final state.
--
-- For a host with no MemoriaHub migration history. A host that already ran the web app's history
-- (it holds prisma/migrations/20260610000000_add_media_domain) adopts this file without running it:
-- `memoriahub-db sync` records it in prisma/memoriahub.lock and writes nothing.
--
-- Requires the platform schema first (users, organizations with is_default, groups, storage_objects,
-- worker_nodes, personal_access_tokens) and the `vector` extension (never created here).
-- Generated by scripts/memoriahub-packages/generate-domain-baseline.mjs from a database migrated with
-- the web app's history; verified equal to it by packages/memoriahub-db/test/apply.db.test.ts.

-- Enums
CREATE TYPE public."BurstGroupStatus" AS ENUM ('pending', 'resolved', 'dismissed');

CREATE TYPE public."DuplicateGroupStatus" AS ENUM ('pending', 'resolved', 'dismissed');

CREATE TYPE public."InsightsSnapshotStatus" AS ENUM ('computing', 'ready', 'failed');

CREATE TYPE public."LocationGroupLevel" AS ENUM ('country', 'region', 'locality');

CREATE TYPE public."LocationSuggestionStatus" AS ENUM ('pending', 'accepted', 'rejected', 'auto_applied', 'reverted');

CREATE TYPE public."MediaEnhancementDecision" AS ENUM ('keep_both', 'replace');

CREATE TYPE public."MediaEnhancementStatus" AS ENUM ('pending', 'processing', 'ready', 'failed', 'applied', 'discarded', 'expired', 'cancelled');

CREATE TYPE public."MediaFaceStatusType" AS ENUM ('not_processed', 'pending', 'processing', 'processed', 'failed', 'no_faces');

CREATE TYPE public."MediaMetadataStatusType" AS ENUM ('not_processed', 'pending', 'processing', 'processed', 'failed');

CREATE TYPE public."MediaSocialStatusType" AS ENUM ('not_processed', 'pending', 'processing', 'processed', 'failed');

CREATE TYPE public."MediaSource" AS ENUM ('web', 'cli', 'android', 'import', 'sync');

CREATE TYPE public."MediaSyncDeviceStatus" AS ENUM ('active', 'revoked');

CREATE TYPE public."MediaSyncRunStatus" AS ENUM ('ok', 'partial', 'failed', 'skipped', 'paused');

CREATE TYPE public."MediaSyncTrigger" AS ENUM ('periodic', 'content_trigger', 'manual', 'app_open', 'initial');

CREATE TYPE public."MediaTagSource" AS ENUM ('manual', 'ai', 'system');

CREATE TYPE public."MediaTagStatusType" AS ENUM ('not_processed', 'pending', 'processing', 'processed', 'failed');

CREATE TYPE public."MediaType" AS ENUM ('photo', 'video');

CREATE TYPE public."MemoryType" AS ENUM ('on_this_day', 'trip', 'person_highlights', 'person_over_years', 'theme', 'seasonal', 'year_in_review');

CREATE TYPE public."NodeBackupRunKind" AS ENUM ('incremental', 'reconcile');

CREATE TYPE public."NodeBackupRunStatus" AS ENUM ('running', 'completed', 'failed', 'aborted', 'stale');

CREATE TYPE public."ReviewRunAction" AS ENUM ('resolve_archive', 'resolve_trash', 'dismiss', 'accept', 'reject');

CREATE TYPE public."ReviewRunItemStatus" AS ENUM ('matched', 'processing', 'applied', 'failed', 'skipped');

CREATE TYPE public."ReviewRunStatus" AS ENUM ('evaluating', 'running', 'completed', 'completed_with_errors', 'failed', 'cancelled');

CREATE TYPE public."ReviewRunSubject" AS ENUM ('burst_group', 'duplicate_group', 'location_suggestion');

CREATE TYPE public."TrashEmptyRunItemStatus" AS ENUM ('matched', 'deleted', 'failed', 'skipped');

CREATE TYPE public."TrashEmptyRunStatus" AS ENUM ('evaluating', 'running', 'completed', 'completed_with_errors', 'failed', 'cancelled');

CREATE TYPE public."WorkflowRunItemStatus" AS ENUM ('matched', 'excluded', 'applied', 'partially_applied', 'failed', 'skipped');

CREATE TYPE public."WorkflowRunStatus" AS ENUM ('evaluating', 'awaiting_approval', 'running', 'completed', 'completed_with_errors', 'failed', 'cancelled', 'expired');

CREATE TYPE public."WorkflowSubject" AS ENUM ('media_item');

CREATE TYPE public."WorkflowTrigger" AS ENUM ('manual', 'on_media_enriched', 'scheduled');

-- Functions
CREATE OR REPLACE FUNCTION public.mh_default_org_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$ SELECT id FROM organizations WHERE is_default LIMIT 1 $function$
;

CREATE OR REPLACE FUNCTION public.face_embedding_to_vector(embedding double precision[])
 RETURNS vector
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF array_length(embedding, 1) = 128 THEN
    RETURN ('[' || array_to_string(embedding, ',') || ']')::vector;
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.faces_sync_embedding_vec()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.embedding_vec := face_embedding_to_vector(NEW.embedding);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.mh_content_owner_from_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  owner uuid;
BEGIN
  NEW."org_id" := COALESCE(NEW."org_id", mh_default_org_id());
  IF EXISTS (SELECT 1 FROM "groups" g WHERE g."id" = NEW."circle_id") THEN
    NEW."owner_group_id" := NEW."circle_id";
    NEW."owner_user_id" := NULL;
  ELSE
    SELECT p."user_id" INTO owner FROM "personal_libraries" p WHERE p."id" = NEW."circle_id";
    IF NOT FOUND THEN
      RAISE EXCEPTION 'RETRO-K2: scope % is neither a group nor a personal library', NEW."circle_id"
        USING ERRCODE = '23503';
    END IF;
    NEW."owner_user_id" := owner;
    NEW."owner_group_id" := NULL;
  END IF;
  RETURN NEW;
END $function$
;

